<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher} from 'svelte';
 import {EnterpriseServices,type Project} from './company-services';
 export let companyId:string;export let actorId:string;export let accessSignal:AbortSignal;
 const dispatch=createEventDispatcher();let service:EnterpriseServices|null=null,items:Project[]=[],query='',error='',loading=true,creating=false,canCreate=false,form=false,title='',body='',uncertain=false;
 let mounted=false,seenCompany='',seenActor='',seenSignal:AbortSignal,timer:ReturnType<typeof setInterval>;let detach=()=>{};
 $: visible=items.filter(p=>(p.title+' '+p.body).toLowerCase().includes(query.toLowerCase()));
 function clear(){service?.close();service=null;items=[];title='';body='';query='';canCreate=false;form=false;loading=false;creating=false;uncertain=false;}
 function fail(cause:any){if(cause.name==='AbortError')return;error=cause.message||'Company projects are unavailable.';if(cause.status===401||cause.companyDenied){clear();dispatch('denied',{status:cause.status});}}
 async function load(){const current=service;if(!current||creating)return;loading=true;error='';try{const scope=await current.authority(),rows=await current.projects();if(current!==service)return;current.current();canCreate=scope.capabilities.includes('files.manage');items=rows;return true;}catch(e){if(current===service){items=[];canCreate=false;fail(e);}return false;}finally{if(current===service)loading=false;}}
 async function create(){const current=service;if(!current||creating||uncertain)return;creating=true;error='';try{const row=await current.createProject(title,body);if(current!==service)return;current.current();items=[row,...items.filter(p=>p.id!==row.id)];form=false;title='';body='';dispatch('created',current.ref(row));}catch(e){if(current===service){uncertain=(e as any).uncertain===true;fail(e);}}finally{if(current===service)creating=false;}}
 function open(row:Project){try{if(service)dispatch('open',service.ref(row));}catch(e){fail(e);}}
 function start(){detach();clear();seenCompany=companyId;seenActor=actorId;seenSignal=accessSignal;service=new EnterpriseServices(companyId,actorId,accessSignal);const parent=accessSignal;const lost=()=>{clear();};parent.addEventListener('abort',lost,{once:true});detach=()=>parent.removeEventListener('abort',lost);void load();}
 function session(e:StorageEvent){if(e.key==='token'||e.key===null){clear();error='Your session changed. Reopen Projects.';dispatch('denied',{status:401});}}
 $: if(mounted&&(companyId!==seenCompany||actorId!==seenActor||accessSignal!==seenSignal))start();
 onMount(()=>{mounted=true;timer=setInterval(()=>{if(!document.hidden&&!form&&!loading)void load();},7000);});onDestroy(()=>{mounted=false;clearInterval(timer);detach();clear();});
 const modified=(n:number)=>new Date(n*1000).toLocaleDateString(undefined,{month:'short',day:'numeric'});
</script>
<svelte:window on:storage={session}/>
<section class="projects"><header><div><h2>Projects</h2><p>Company-owned work, files and plans.</p></div><button class="primary" disabled={!canCreate||creating} on:click={()=>form=!form}>New project</button></header>
<div class="toolbar"><label><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/></svg><input aria-label="Search company projects" placeholder="Search projects…" bind:value={query}/></label><button disabled={loading||creating} on:click={load}>Refresh</button></div>
{#if form}<form class="create" on:submit|preventDefault={create}><h3>New company project</h3><p>Create a project record. Website builds and deployments are separate actions you can request in chat.</p><label>Name<input bind:value={title} maxlength="240" required disabled={creating}/></label><label>Brief<textarea bind:value={body} rows="3" maxlength="100000" disabled={creating}/></label><div class="actions"><button type="button" disabled={creating} on:click={()=>form=false}>Cancel</button><button class="primary" disabled={creating||uncertain||!title.trim()}>{creating?'Creating…':'Create project'}</button></div>{#if uncertain}<p class="error">Creation is unconfirmed. Refresh the list before trying again.<button type="button" on:click={async()=>{if(await load())uncertain=false;}}>Check projects</button></p>{/if}</form>{/if}
{#if error}<p role="alert" class="error">{error}</p>{/if}{#if loading&&!items.length}<p class="empty" role="status">Loading company projects…</p>{:else}<div class="grid">{#each visible as item(item.id)}<button class="card" on:click={()=>open(item)}><span class="project-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M3 7h7l2 2h9v11H3Z"/><path d="M3 7V4h7l2 3"/></svg></span><h3>{item.title}</h3><p>{item.body?item.body.slice(0,160):'No brief added yet.'}</p><footer><span>Revision {item.version}</span><span>{modified(item.modified)}</span></footer></button>{:else}<div class="empty"><h3>{query?'No matching projects':'No company projects yet'}</h3><p>{query?'Try a different search.':'Create a project or ask a bot to organize your next piece of work.'}</p></div>{/each}</div>{/if}<small class="limit">Up to 200 accessible company projects are shown. Personal projects are kept separate.</small></section>
<style>.projects{width:100%;max-width:1180px;margin:auto;padding:36px 42px;color:#17243f;overflow:auto;height:100%}header{display:flex;align-items:center;justify-content:space-between;gap:16px}h2{font-size:25px;font-weight:550;letter-spacing:-.7px;margin:0}header p{font-size:12px;color:#8b96aa;margin-top:7px}button,input,textarea{font:inherit}button{cursor:pointer}button:disabled{opacity:.45;cursor:default}.primary{border:0;border-radius:8px;padding:9px 14px;background:#3466f6;color:#fff;font-size:12px;white-space:nowrap}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:30px 0 22px}.toolbar label{display:flex;align-items:center;gap:8px;background:#f6f8fc;border:1px solid #e6ebf4;border-radius:8px;padding:9px 12px;max-width:340px;width:100%}.toolbar svg{width:16px;height:16px;color:#8f9cb0;flex:none}.toolbar input{border:0;background:none;outline:none;width:100%;font-size:12px}.toolbar button,.actions>button:not(.primary){background:none;border:0;color:#8793a8;font-size:11px;padding:8px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.card{display:flex;flex-direction:column;align-items:flex-start;text-align:left;background:#fff;border:1px solid #e6ebf4;border-radius:12px;min-height:215px;padding:23px;color:inherit}.card:hover{border-color:#afc2fb;box-shadow:0 4px 20px #3466f609}.project-icon{display:grid;place-items:center;background:#eef3ff;border-radius:10px;width:40px;height:40px;color:#6c8bdb}.project-icon svg{width:22px;height:22px}h3{font-size:14px;font-weight:550;margin:17px 0 6px}.card p{font-size:11px;line-height:1.7;color:#939eb1;margin:0 0 20px;overflow-wrap:anywhere}.card footer{display:flex;justify-content:space-between;gap:10px;border-top:1px solid #eef1f6;width:100%;padding-top:12px;margin-top:auto;color:#9da7b8;font-size:10px}.empty{grid-column:1/-1;padding:55px 20px;text-align:center;color:#99a4b6;font-size:12px}.empty h3{font-size:17px}.empty p{font-size:12px}.limit{display:block;font-size:10px;color:#a6afbd;margin:20px 0}.create{background:#f9fbff;border:1px solid #e1e8f6;border-radius:12px;padding:22px;margin-bottom:22px}.create h3{margin:0}.create p{font-size:11px;line-height:1.7;color:#8996ac}.create label{display:flex;flex-direction:column;gap:6px;font-size:11px;color:#7b8ba3;margin:14px 0}.create input,.create textarea{border:1px solid #e1e7f2;border-radius:7px;background:#fff;padding:9px 11px;color:#17243f;width:100%;font-size:12px}.actions{display:flex;justify-content:flex-end;gap:8px}.error{color:#ad4b52;font-size:12px;line-height:1.7;overflow-wrap:anywhere}.error button{margin-left:8px;border:0;background:none;text-decoration:underline;color:inherit}button:focus-visible,input:focus-visible,textarea:focus-visible{outline:2px solid #789bff;outline-offset:3px}@media(max-width:1150px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.projects{padding:26px 22px}.grid{grid-template-columns:1fr}h2{font-size:23px}header{align-items:flex-start}.primary{font-size:11px}.toolbar{margin-top:24px}}</style>
